import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"24、【复】 震下坤上","description":"横渠易说 - 24、【复】 震下坤上","frontmatter":{"title":"24、【复】 震下坤上","description":"横渠易说 - 24、【复】 震下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/026.md","filePath":"zh/classics/hengqu/026.md"}'),l={name:"zh/classics/hengqu/026.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_24、【复】-震下坤上" tabindex="-1">24、【复】 震下坤上 <a class="header-anchor" href="#_24、【复】-震下坤上" aria-label="Permalink to “24、【复】 震下坤上”">​</a></h1><p>静之动也无休息之期，故地雷为卦，言反又言复，终则有始，循环无穷，入，指其化而裁之耳。深其反也，几其复也，故曰“反复其道”，又曰“出入无疾”。</p><h3 id="彖曰-复亨-刚反动而以顺行-是以-出入无疾-朋来无咎-。-反复其道-七日来复-天行也-利有攸往-刚长也。复其见天地之心乎" tabindex="-1">彖曰：复亨，刚反动而以顺行，是以“出入无疾，朋来无咎”。“反复其道，七日来复”，天行也；“利有攸往”，刚长也。复其见天地之心乎! <a class="header-anchor" href="#彖曰-复亨-刚反动而以顺行-是以-出入无疾-朋来无咎-。-反复其道-七日来复-天行也-利有攸往-刚长也。复其见天地之心乎" aria-label="Permalink to “彖曰：复亨，刚反动而以顺行，是以“出入无疾，朋来无咎”。“反复其道，七日来复”，天行也；“利有攸往”，刚长也。复其见天地之心乎!”">​</a></h3><p>复言“天地之心”，咸、恒、大壮言“天地之情”。心，内也，其原在内时，则有形见，情则见于事也，故可得而名状。自姤而剥，至于上九，其数六也。剥之与复，不可容线，须臾不复，则乾坤之道息也，故适尽即生，更无先后之次也。此义最大。临卦“至于八月有凶”，此言“七日来复”，何也？刚长之时，豫戒以阴长之事，故言“至于八月有凶”；若复则不可须臾断，故言“七日”。七日者，画夜相继，元无断续之时也。大抵言“天地之心”者，天地之大德曰生，则以生物为本者，乃天地之心也。地雷见天地之心者，天地之心惟是生物，天地之大德曰生也。雷复于地中，却是生物。彖曰：“终则有始，天行也。”天行何尝有息？正以静，有何期程？此动是静中之动，静中之动，动而不穷，又有甚首尾起灭？自有天地以来以迄于今，盖为静而动。天则无心无为，无所主宰，恒然如此，有何休歇？人之德性亦与此合，乃是己有，苟心中造作安排而静，则安能久!然必从此去，盖静者进德之基也。</p><h3 id="象曰-雷在地中-复-先王以至日闭关-商旅不行-后不省方。" tabindex="-1">象曰：雷在地中，复，先王以至日闭关，商旅不行，后不省方。 <a class="header-anchor" href="#象曰-雷在地中-复-先王以至日闭关-商旅不行-后不省方。" aria-label="Permalink to “象曰：雷在地中，复，先王以至日闭关，商旅不行，后不省方。”">​</a></h3><p>凡言“后”者，大率谓继体守成之主也。复言“先王以至日闭关，商旅不行，后不省方”，以此校之，则后为继承之主明矣。“先王以至日闭关”者，先王所重于至日，以其顺阴阳往来，“闭关”者，取其静也，闭关则商旅不行。先王无放过事，顺时以示法，亦以示民。“后不省方”，如言富庶优暇，不甚省事，又明是继文之主。</p><h3 id="初九-不远复-无只悔-元吉。-象曰-不远之复-以修身也。" tabindex="-1">初九，不远复，无只悔，元吉。 象曰：不远之复，以修身也。 <a class="header-anchor" href="#初九-不远复-无只悔-元吉。-象曰-不远之复-以修身也。" aria-label="Permalink to “初九，不远复，无只悔，元吉。 象曰：不远之复，以修身也。”">​</a></h3><p>祗犹承也，受也。一云：祗悔作神祗之祗。祗之为义，示也，效也，见也，言悔可使亡，不可使成而形也。</p><h3 id="六二-休复-吉。-象曰-休复之吉-以下仁也。" tabindex="-1">六二，休复，吉。 象曰：休复之吉，以下仁也。 <a class="header-anchor" href="#六二-休复-吉。-象曰-休复之吉-以下仁也。" aria-label="Permalink to “六二，休复，吉。 象曰：休复之吉，以下仁也。”">​</a></h3><p>下比于阳，故乐行其善。</p><h3 id="六三-频复-厉无咎。-象曰-频复之厉-义无咎也-。" tabindex="-1">六三，频复，厉无咎。 象曰：频复之厉，义无咎也”。 <a class="header-anchor" href="#六三-频复-厉无咎。-象曰-频复之厉-义无咎也-。" aria-label="Permalink to “六三，频复，厉无咎。 象曰：频复之厉，义无咎也”。”">​</a></h3><p>所处非位，非频蹙自危，不能无吝。吝一作咎。</p><h3 id="六四-中行独复。-象曰-中行独复-以从道也。" tabindex="-1">六四，中行独复。 象曰：“中行独复”，以从道也。 <a class="header-anchor" href="#六四-中行独复。-象曰-中行独复-以从道也。" aria-label="Permalink to “六四，中行独复。 象曰：“中行独复”，以从道也。”">​</a></h3><p>柔危之世，以中道合正应，故不与群爻同。</p><h3 id="六五-敦复-无悔。-象曰-敦复无悔-中以自考也。" tabindex="-1">六五，敦复，无悔。 象曰：“敦复无悔”，中以自考也。 <a class="header-anchor" href="#六五-敦复-无悔。-象曰-敦复无悔-中以自考也。" aria-label="Permalink to “六五，敦复，无悔。 象曰：“敦复无悔”，中以自考也。”">​</a></h3><p>性顺位中，无它应援，以敦实自求而已。刚长柔危之世，能以中道自考，故可无悔，不然，取悔必矣。</p><h3 id="上六-迷复-凶-有灾眚。用行师-终有大败-以其国君凶-至于十年不克征。-象曰-迷复之凶-反君道也。" tabindex="-1">上六，迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。 象曰：迷复之凶，反君道也。 <a class="header-anchor" href="#上六-迷复-凶-有灾眚。用行师-终有大败-以其国君凶-至于十年不克征。-象曰-迷复之凶-反君道也。" aria-label="Permalink to “上六，迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。 象曰：迷复之凶，反君道也。”">​</a></h3><p>君道过亢反常，无施而可，故天灾人害，师败君凶，久衰而不可振也。</p>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
